mapper.select:
SELECT  FROM crm_material_revision r
WHERE r.tenant_id=#{tenantId} AND r.material_id=#{materialId} AND r.revision_no=#{revisionNo}
  AND r.created_by=#{createdBy}

mapper.update:
UPDATE crm_material
SET latest_revision_id=#{latestRevisionId}
WHERE tenant_id=#{tenantId} AND id=#{materialId}
